import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI } from "@google/genai";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const PORT = 3000;

app.use(express.json());

// Lazy-initialized Gemini API client
let aiClient: GoogleGenAI | null = null;
function getAi(): GoogleGenAI {
  if (!aiClient) {
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      throw new Error("La variable GEMINI_API_KEY no está configurada. Por favor, añádela en la configuración de Secrets.");
    }
    aiClient = new GoogleGenAI({ apiKey });
  }
  return aiClient;
}

// REST API endpoint for intelligent diagnostics with trained agent context
app.post("/api/generate-diagnostic", async (req, res) => {
  try {
    const {
      clientCompany,
      clientBizType,
      clientBottleneck,
      clientWastedHours,
      clientTools,
      diagnosticoHourlyCost,
      isUnlocked,
      agentName,
      agentTone,
      agentInstructions,
      agentSkills
    } = req.body;

    const ai = getAi();

    // Format agent custom skills to feed the systemic prompt context
    const formattedSkills = Array.isArray(agentSkills)
      ? agentSkills.map((s: any) => `- Habilidad: ${s.Habilidad || s.skill || ""} | Categoría: ${s.Categoria || s.category || ""} | Impacto: ${s.Impacto || s.impact || ""}`).join("\n")
      : "No se cargaron habilidades adicionales de especialización.";

    // Structured System Prompt explaining the exact expert persona & inputs
    const systemPrompt = `Eres un Arquitecto de Soluciones de IA y Consultor de Inteligencia Organizacional.
Tu título profesional es: "${agentName || "Director de Inteligencia Organizacional"}".
Tu tono de voz y personalidad: "${agentTone || "Analítico, de taller, enfocado en resolver fricciones operativas y acelerar el retorno de inversión"}".
Tus lineamientos y directivas de entrenamiento adicionales: "${agentInstructions || "Optimizar procesos manuales, automatizar flujos con scripts interconectados y dashboards a medida."}".
Tus habilidades clave cargadas para este diagnóstico son:
${formattedSkills}

Tu misión es realizar un análisis estratégico personalizado basándote en los datos reportados por el cliente de forma detallada, analítica e inteligente (sin generalidades clichés corporativas). Debes entregar:
1. Una arquitectura tecnológica recomendada detallada, interactiva y robusta (de unas 2 o 3 oraciones, redactada de forma directa y elegante en español), que mencione al cliente por su nombre ("${clientCompany || "tu proyecto"}") y resuelva de raíz su cuello de botella o fricción manual expresada: "${clientBottleneck || "ineficiencias operativas"}". Propón herramientas concretas o integraciones técnicas como scripts, automatización de bases de datos, webhooks, almacenamiento en la nube o plantillas a medida según tu catálogo de habilidades.
2. Un plan de acción estructurado de 3 fases (Fase 1, Fase 2, Fase 3) que defina la secuencia óptima para pasar del caos manual al orden automatizado, alineado con las herramientas actuales del cliente: "${clientTools || "registros tradicionales"}" y su modelo de negocio: "${clientBizType}".

Datos provistos para el análisis:
- Empresa/Proyecto: "${clientCompany || "tu negocio"}"
- Modelo de Operación: "${clientBizType}"
- Costo operario o de hora: $${diagnosticoHourlyCost || 25} USD/h
- Horas desperdiciadas semanalmente: ${clientWastedHours || 15} hrs/sem
- Principal Cuello de Botella / Fricción: "${clientBottleneck || "Procesos manuales ruidosos"}"
- Herramientas usadas actualmente: "${clientTools || "Excel, cuadernos y chats"}"

Debes responder ÚNICAMENTE con un objeto JSON válido que encaje perfectamente con este esquema:
{
  "architecture": "Redacción de la propuesta de arquitectura tecnológica y flujos integrados a medida en español.",
  "fases": [
    {
      "title": "Fase 01: [Título descriptivo personalizado en español]",
      "desc": "Descripción detallada de las acciones iniciales de depuración estructural."
    },
    {
      "title": "Fase 02: [Título descriptivo personalizado en español]",
      "desc": "Descripción detallada del desarrollo del motor de automatización sincrónico o módulo principal."
    },
    {
      "title": "Fase 03: [Título descriptivo personalizado en español]",
      "desc": "Descripción detallada del despliegue final, controles visuales en vivo y reportes de rentabilidad."
    }
  ]
}`;

    // Query Gemini
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: [
        { role: "user", parts: [{ text: "Genera el diagnóstico estratégico inteligente para mi empresa según tus habilidades aplicables." }] }
      ],
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        temperature: 0.75,
      }
    });

    const parsedOutput = JSON.parse(response.text || "{}");

    res.json({
      success: true,
      data: parsedOutput
    });

  } catch (error: any) {
    console.error("Gemini API Diagnostic Error:", error);
    res.status(500).json({
      success: false,
      error: error.message || "Error al generar el diagnóstico inteligente."
    });
  }
});

// Serve static resources and load Vite on development
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server is running fully backend integrated on http://localhost:${PORT}`);
  });
}

startServer();
